//! `omr-winres`: build-time Windows resources (the app icon and VERSIONINFO) for the Mizan
//! executables, written directly as a `.res` file (MSVC) or a COFF object (GNU), so a Windows build
//! needs no resource compiler. See the README for use from a `build.rs`.
#![forbid(unsafe_code)]

use std::env;
use std::fs;
use std::path::PathBuf;

/// The Mizan icon: 16 to 256 px, generated by `cargo run -p shell-slint --example brand_icons`.
pub const ICON: &[u8] = include_bytes!("../assets/mizan.ico");

/// The per-executable strings of the version resource.
#[derive(Debug, Clone, Copy)]
pub struct Info<'a> {
    /// Shown by Explorer and Task Manager, e.g. "Mizan".
    pub file_description: &'a str,
    /// The executable's file name, e.g. "omr-desktop.exe".
    pub original_filename: &'a str,
}

/// One resource with a numeric type and name: (type, name, language, data).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Resource {
    pub kind: u16,
    pub id: u16,
    pub lang: u16,
    pub data: Vec<u8>,
}

const RT_ICON: u16 = 3;
const RT_GROUP_ICON: u16 = 14;
const RT_VERSION: u16 = 16;
const LANG_EN_US: u16 = 0x0409;

/// Embeds the icon and version resource into every binary of the calling package when it is built
/// for Windows; does nothing for other targets. Call from `build.rs`. Panics (failing the build)
/// on a broken icon or an unwritable `OUT_DIR`, so a Windows build never ships without its icon.
pub fn embed(info: &Info) {
    if env::var("CARGO_CFG_TARGET_OS").as_deref() != Ok("windows") {
        return;
    }
    let version = parse_version(&env::var("CARGO_PKG_VERSION").unwrap_or_default());
    let resources = resources(ICON, version, info).expect("omr-winres: assets/mizan.ico");
    let out = PathBuf::from(env::var("OUT_DIR").expect("OUT_DIR"));
    let (file, bytes) = if env::var("CARGO_CFG_TARGET_ENV").as_deref() == Ok("msvc") {
        ("mizan.res", res_file(&resources))
    } else {
        let machine = match env::var("CARGO_CFG_TARGET_ARCH").as_deref() {
            Ok("x86_64") => Machine::X64,
            Ok("aarch64") => Machine::Arm64,
            Ok("x86") => Machine::X86,
            other => panic!("omr-winres: no COFF writer for architecture {other:?}"),
        };
        ("mizan-res.o", coff_object(&resources, machine))
    };
    let path = out.join(file);
    fs::write(&path, bytes).expect("omr-winres: write the resource file");
    println!("cargo:rustc-link-arg-bins={}", path.display());
}

/// "0.1.0" → [0, 1, 0, 0]; missing or non-numeric parts are 0.
pub fn parse_version(v: &str) -> [u16; 4] {
    let mut out = [0u16; 4];
    for (slot, part) in out.iter_mut().zip(v.split(['.', '-', '+'])) {
        *slot = part.parse().unwrap_or(0);
    }
    out
}

/// The icon images (one RT_ICON each), the icon group (RT_GROUP_ICON 1, the executable's icon)
/// and the version resource (RT_VERSION 1).
pub fn resources(ico: &[u8], version: [u16; 4], info: &Info) -> Result<Vec<Resource>, String> {
    let rd16 = |o: usize| -> Result<u16, String> {
        ico.get(o..o + 2)
            .map(|b| u16::from_le_bytes([b[0], b[1]]))
            .ok_or_else(|| "truncated icon directory".to_string())
    };
    let rd32 = |o: usize| -> Result<u32, String> {
        ico.get(o..o + 4)
            .map(|b| u32::from_le_bytes([b[0], b[1], b[2], b[3]]))
            .ok_or_else(|| "truncated icon directory".to_string())
    };
    if (rd16(0)?, rd16(2)?) != (0, 1) {
        return Err("not an .ico file".into());
    }
    let n = rd16(4)? as usize;
    if n == 0 {
        return Err("the icon has no images".into());
    }
    let mut out = Vec::with_capacity(n + 2);
    // GRPICONDIR, then one 14-byte GRPICONDIRENTRY per image (the ICONDIRENTRY with the file
    // offset replaced by the RT_ICON id).
    let mut group = Vec::new();
    for x in [0u16, 1, n as u16] {
        group.extend(x.to_le_bytes());
    }
    for i in 0..n {
        let d = 6 + 16 * i;
        let (size, offset) = (rd32(d + 8)? as usize, rd32(d + 12)? as usize);
        let image = ico
            .get(offset..offset + size)
            .ok_or_else(|| format!("icon image {i} lies outside the file"))?;
        let id = (i + 1) as u16;
        out.push(Resource {
            kind: RT_ICON,
            id,
            lang: LANG_EN_US,
            data: image.to_vec(),
        });
        group.extend(&ico[d..d + 12]);
        group.extend(id.to_le_bytes());
    }
    out.push(Resource {
        kind: RT_GROUP_ICON,
        id: 1,
        lang: LANG_EN_US,
        data: group,
    });
    out.push(Resource {
        kind: RT_VERSION,
        id: 1,
        lang: LANG_EN_US,
        data: version_info(version, info),
    });
    Ok(out)
}

fn utf16z(s: &str) -> Vec<u8> {
    s.encode_utf16()
        .chain([0])
        .flat_map(u16::to_le_bytes)
        .collect()
}

fn pad4(v: &mut Vec<u8>) {
    while !v.len().is_multiple_of(4) {
        v.push(0);
    }
}

/// One VERSIONINFO block: wLength, wValueLength, wType, key, value, children (each 4-aligned).
fn block(key: &str, value: &[u8], value_len: u16, text: bool, children: &[Vec<u8>]) -> Vec<u8> {
    let mut v = vec![0u8; 6];
    v.extend(utf16z(key));
    pad4(&mut v);
    v.extend(value);
    for c in children {
        pad4(&mut v);
        v.extend(c);
    }
    let len = v.len() as u16;
    v[0..2].copy_from_slice(&len.to_le_bytes());
    v[2..4].copy_from_slice(&value_len.to_le_bytes());
    v[4..6].copy_from_slice(&u16::from(text).to_le_bytes());
    v
}

fn string(key: &str, value: &str) -> Vec<u8> {
    let w = utf16z(value);
    block(key, &w, (w.len() / 2) as u16, true, &[])
}

fn version_info(v: [u16; 4], info: &Info) -> Vec<u8> {
    let ms = (u32::from(v[0]) << 16) | u32::from(v[1]);
    let ls = (u32::from(v[2]) << 16) | u32::from(v[3]);
    let mut fixed = Vec::new();
    // VS_FIXEDFILEINFO: signature, struct version, file and product versions, flags mask,
    // flags, VOS_NT_WINDOWS32, VFT_APP, no subtype, no date.
    for x in [
        0xFEEF_04BDu32,
        0x0001_0000,
        ms,
        ls,
        ms,
        ls,
        0x3F,
        0,
        0x0004_0004,
        1,
        0,
        0,
        0,
    ] {
        fixed.extend(x.to_le_bytes());
    }
    let text = format!("{}.{}.{}.{}", v[0], v[1], v[2], v[3]);
    let table = block(
        "040904B0",
        &[],
        0,
        true,
        &[
            string("FileDescription", info.file_description),
            string("FileVersion", &text),
            string("InternalName", info.original_filename),
            string("OriginalFilename", info.original_filename),
            string("ProductName", "Mizan"),
            string("ProductVersion", &text),
        ],
    );
    let strings = block("StringFileInfo", &[], 0, true, &[table]);
    let translation = (u32::from(LANG_EN_US) | (1200 << 16)).to_le_bytes(); // en-US, UTF-16
    let var = block("Translation", &translation, 4, false, &[]);
    let vars = block("VarFileInfo", &[], 0, true, &[var]);
    block("VS_VERSION_INFO", &fixed, 52, false, &[strings, vars])
}

/// A 32-bit `.res` file: the empty leading entry, then each resource with its header.
pub fn res_file(resources: &[Resource]) -> Vec<u8> {
    let mut out = Vec::new();
    let mut entry = |kind: u16, id: u16, flags: u16, lang: u16, data: &[u8]| {
        out.extend((data.len() as u32).to_le_bytes()); // DataSize
        out.extend(32u32.to_le_bytes()); // HeaderSize
        for x in [0xFFFFu16, kind, 0xFFFF, id] {
            out.extend(x.to_le_bytes()); // numeric TYPE and NAME
        }
        out.extend(0u32.to_le_bytes()); // DataVersion
        out.extend(flags.to_le_bytes()); // MemoryFlags
        out.extend(lang.to_le_bytes()); // LanguageId
        out.extend([0u8; 8]); // Version, Characteristics
        out.extend(data);
        pad4(&mut out);
    };
    entry(0, 0, 0, 0, &[]);
    for r in resources {
        let flags = match r.kind {
            RT_ICON => 0x1010,       // moveable, discardable
            RT_GROUP_ICON => 0x1030, // moveable, pure, discardable
            _ => 0x0030,             // moveable, pure
        };
        entry(r.kind, r.id, flags, r.lang, &r.data);
    }
    out
}

/// The COFF machine of a GNU object.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Machine {
    X64,
    Arm64,
    X86,
}

impl Machine {
    /// (IMAGE_FILE_MACHINE_*, the image-relative 32-bit relocation type).
    fn codes(self) -> (u16, u16) {
        match self {
            Machine::X64 => (0x8664, 3),   // IMAGE_REL_AMD64_ADDR32NB
            Machine::Arm64 => (0xAA64, 2), // IMAGE_REL_ARM64_ADDR32NB
            Machine::X86 => (0x014C, 7),   // IMAGE_REL_I386_DIR32NB
        }
    }
}

/// A COFF object with one `.rsrc` section (the resource directory tree and the data) for GNU
/// `ld`, which does not read `.res` files. Each data entry's RVA is an image-relative relocation
/// against the section symbol; its addend is the data's offset in the section.
pub fn coff_object(resources: &[Resource], machine: Machine) -> Vec<u8> {
    let mut res: Vec<&Resource> = resources.iter().collect();
    res.sort_by_key(|r| (r.kind, r.id, r.lang));
    let mut kinds: Vec<u16> = res.iter().map(|r| r.kind).collect();
    kinds.dedup();
    let dir_size = |entries: usize| 16 + 8 * entries;
    // layout: root directory, one directory per type, one per name (one language each), the data
    // entries, then the data (8-aligned)
    let mut size = dir_size(kinds.len());
    let kind_dir: Vec<usize> = kinds
        .iter()
        .map(|k| {
            let at = size;
            size += dir_size(res.iter().filter(|r| r.kind == *k).count());
            at
        })
        .collect();
    let name_dir: Vec<usize> = res
        .iter()
        .map(|_| {
            let at = size;
            size += dir_size(1);
            at
        })
        .collect();
    let data_entry: Vec<usize> = res
        .iter()
        .map(|_| {
            let at = size;
            size += 16;
            at
        })
        .collect();
    let data_at: Vec<usize> = res
        .iter()
        .map(|r| {
            let at = size;
            size += (r.data.len() + 7) & !7;
            at
        })
        .collect();
    let mut sec = vec![0u8; size];
    let put =
        |sec: &mut Vec<u8>, at: usize, v: u32| sec[at..at + 4].copy_from_slice(&v.to_le_bytes());
    // IMAGE_RESOURCE_DIRECTORY: only NumberOfIdEntries (offset 14) is set
    let ids = |sec: &mut Vec<u8>, at: usize, n: usize| {
        sec[at + 14..at + 16].copy_from_slice(&(n as u16).to_le_bytes())
    };
    ids(&mut sec, 0, kinds.len());
    for (i, k) in kinds.iter().enumerate() {
        put(&mut sec, 16 + 8 * i, u32::from(*k));
        put(&mut sec, 20 + 8 * i, 0x8000_0000 | kind_dir[i] as u32);
        let mine: Vec<usize> = (0..res.len()).filter(|&j| res[j].kind == *k).collect();
        ids(&mut sec, kind_dir[i], mine.len());
        for (slot, &j) in mine.iter().enumerate() {
            put(&mut sec, kind_dir[i] + 16 + 8 * slot, u32::from(res[j].id));
            put(
                &mut sec,
                kind_dir[i] + 20 + 8 * slot,
                0x8000_0000 | name_dir[j] as u32,
            );
        }
    }
    let (machine_code, reloc_type) = machine.codes();
    let mut relocs = Vec::new();
    for j in 0..res.len() {
        ids(&mut sec, name_dir[j], 1);
        put(&mut sec, name_dir[j] + 16, u32::from(res[j].lang));
        put(&mut sec, name_dir[j] + 20, data_entry[j] as u32);
        put(&mut sec, data_entry[j], data_at[j] as u32); // addend; relocated to an RVA
        put(&mut sec, data_entry[j] + 4, res[j].data.len() as u32);
        sec[data_at[j]..data_at[j] + res[j].data.len()].copy_from_slice(&res[j].data);
        relocs.extend((data_entry[j] as u32).to_le_bytes());
        relocs.extend(0u32.to_le_bytes()); // symbol 0: .rsrc
        relocs.extend(reloc_type.to_le_bytes());
    }
    let raw = 20 + 40; // file header + one section header
    let rel = raw + sec.len();
    let symtab = rel + relocs.len();
    let mut o = Vec::new();
    o.extend(machine_code.to_le_bytes());
    o.extend(1u16.to_le_bytes()); // one section
    o.extend(0u32.to_le_bytes()); // no timestamp: deterministic output
    o.extend((symtab as u32).to_le_bytes());
    o.extend(1u32.to_le_bytes()); // one symbol
    o.extend([0u8; 4]); // no optional header, no characteristics
    o.extend(b".rsrc\0\0\0");
    for v in [0u32, 0, sec.len() as u32, raw as u32, rel as u32, 0] {
        o.extend(v.to_le_bytes());
    }
    o.extend((res.len() as u16).to_le_bytes()); // NumberOfRelocations
    o.extend(0u16.to_le_bytes());
    o.extend(0x4000_0040u32.to_le_bytes()); // initialised data, readable
    o.extend(&sec);
    o.extend(&relocs);
    o.extend(b".rsrc\0\0\0"); // the section symbol: value 0, section 1, static, no aux
    o.extend(0u32.to_le_bytes());
    o.extend(1u16.to_le_bytes());
    o.extend(0u16.to_le_bytes());
    o.extend([3u8, 0]);
    o.extend(4u32.to_le_bytes()); // empty string table
    o
}

#[cfg(test)]
mod tests {
    use super::*;

    const INFO: Info = Info {
        file_description: "Mizan",
        original_filename: "omr-desktop.exe",
    };

    fn rd16(b: &[u8], o: usize) -> u16 {
        u16::from_le_bytes([b[o], b[o + 1]])
    }

    fn rd32(b: &[u8], o: usize) -> u32 {
        u32::from_le_bytes(b[o..o + 4].try_into().unwrap())
    }

    /// The committed icon is the one Windows needs: every size the shell asks for, 64 px and up
    /// as PNG, and each smaller one a 32-bit DIB of its stated size.
    #[test]
    fn the_icon_has_every_windows_size() {
        let n = rd16(ICON, 4) as usize;
        let mut sizes = Vec::new();
        for i in 0..n {
            let d = 6 + 16 * i;
            let w = if ICON[d] == 0 {
                256
            } else {
                u32::from(ICON[d])
            };
            let (size, off) = (rd32(ICON, d + 8) as usize, rd32(ICON, d + 12) as usize);
            let image = &ICON[off..off + size];
            if w >= 64 {
                assert_eq!(&image[..8], b"\x89PNG\r\n\x1a\n", "{w} px is PNG");
            } else {
                assert_eq!(rd32(image, 0), 40, "{w} px: BITMAPINFOHEADER");
                assert_eq!(rd32(image, 4), w, "{w} px: width");
                assert_eq!(rd32(image, 8), 2 * w, "{w} px: height (image + mask)");
                assert_eq!(rd16(image, 14), 32, "{w} px: 32 bits per pixel");
            }
            sizes.push(w);
        }
        assert_eq!(
            sizes,
            [16, 20, 24, 30, 32, 36, 40, 48, 60, 64, 72, 80, 96, 128, 256]
        );
    }

    #[test]
    fn the_group_names_every_image_and_the_version_is_parsed() {
        let r = resources(ICON, parse_version("0.1.0"), &INFO).unwrap();
        let icons = r.iter().filter(|x| x.kind == RT_ICON).count();
        let group = r.iter().find(|x| x.kind == RT_GROUP_ICON).unwrap();
        assert_eq!(group.id, 1, "the executable's icon is the lowest group id");
        assert_eq!(rd16(&group.data, 4) as usize, icons);
        assert_eq!(group.data.len(), 6 + 14 * icons);
        for i in 0..icons {
            assert_eq!(rd16(&group.data, 6 + 14 * i + 12) as usize, i + 1);
        }
        assert_eq!(parse_version("1.22.333-preview.4"), [1, 22, 333, 0]);
        let v = &r.iter().find(|x| x.kind == RT_VERSION).unwrap().data;
        assert_eq!(rd16(v, 0) as usize, v.len(), "VS_VERSIONINFO length");
        let text: Vec<u16> = v
            .chunks(2)
            .map(|c| u16::from_le_bytes([c[0], c[1]]))
            .collect();
        let needle: Vec<u16> = "Mizan".encode_utf16().collect();
        assert!(text.windows(needle.len()).any(|w| w == needle));
    }

    #[test]
    fn the_res_file_is_a_sequence_of_aligned_entries() {
        let r = resources(ICON, [0, 1, 0, 0], &INFO).unwrap();
        let res = res_file(&r);
        let mut at = 0;
        let mut seen = Vec::new();
        while at < res.len() {
            let (data, header) = (rd32(&res, at) as usize, rd32(&res, at + 4) as usize);
            assert_eq!(header, 32);
            seen.push((rd16(&res, at + 10), rd16(&res, at + 14)));
            at += header + data;
            at = (at + 3) & !3;
        }
        assert_eq!(at, res.len());
        assert_eq!(seen[0], (0, 0), "the empty leading entry");
        assert_eq!(seen.len(), r.len() + 1);
        assert!(seen.contains(&(RT_GROUP_ICON, 1)));
        assert!(seen.contains(&(RT_VERSION, 1)));
    }

    #[test]
    fn the_coff_object_has_one_relocated_rsrc_section() {
        let r = resources(ICON, [0, 1, 0, 0], &INFO).unwrap();
        let o = coff_object(&r, Machine::X64);
        assert_eq!(rd16(&o, 0), 0x8664);
        assert_eq!(rd16(&o, 2), 1, "one section");
        assert_eq!(&o[20..28], b".rsrc\0\0\0");
        let (raw_size, raw_at, rel_at) = (
            rd32(&o, 36) as usize,
            rd32(&o, 40) as usize,
            rd32(&o, 44) as usize,
        );
        assert_eq!(
            rd16(&o, 52) as usize,
            r.len(),
            "one relocation per data entry"
        );
        assert_eq!(rel_at, raw_at + raw_size);
        let sec = &o[raw_at..raw_at + raw_size];
        assert_eq!(rd16(sec, 14), 3, "three types: icon, group icon, version");
        // each relocation points at a data entry whose addend + size stay inside the section
        for k in 0..r.len() {
            let entry = rd32(&o, rel_at + 10 * k) as usize;
            let (addend, len) = (rd32(sec, entry) as usize, rd32(sec, entry + 4) as usize);
            assert!(addend + len <= sec.len());
            assert_eq!(rd16(&o, rel_at + 10 * k + 8), 3, "IMAGE_REL_AMD64_ADDR32NB");
        }
        assert_eq!(
            rd32(&o, 8) as usize,
            rel_at + 10 * r.len(),
            "symbol table follows"
        );
    }

    #[test]
    fn a_broken_icon_is_refused() {
        assert!(resources(b"not an icon", [0; 4], &INFO).is_err());
        let mut truncated = ICON[..64].to_vec();
        truncated[6 + 8] = 0xFF; // first image size far past the end
        assert!(resources(&truncated, [0; 4], &INFO).is_err());
    }
}
